import * as HO from './holoecho.js?v=122';
import {CATALOG,BY_ID} from './state-catalog.js?v=122';
import * as S from './states.js?v=122';
import * as E from './engine.js?v=122';
const SURVIVAL={impersonation1:{...BY_ID.impersonation,id:'impersonation1',zh:'伪装 IMP-1',icons:[BY_ID.impersonation.icons[0]]},impersonation2:{...BY_ID.impersonation,id:'impersonation2',zh:'伪装 IMP-2',icons:[BY_ID.impersonation.icons[1]]},proxyActive:{id:'proxyActive',en:'Active Proxy',zh:'主动代理体',effect:'本命令正常激活；其他代理体只能Dodge/Reset ARO。',icons:['assets/vendor/wiki/proxy_active0.jpg'],official:true},seedEmbryo:{id:'seedEmbryo',en:'Seed-Embryo',zh:'种胚',effect:'移动或成功闪避时按孵化规则切换。',icons:['assets/symbioMate.svg'],official:false},transmuted:{id:'transmuted',en:'Transmuted',zh:'已变形',effect:'当前使用另一形态；伤口和状态共享。',icons:['assets/vendor/wiki/transmuted0.jpg'],official:true},symbioMate:{id:'symbioMate',en:'SymbioMate',zh:'共生防护',effect:'一次性装备；被迫过保时启用，命令末消耗。',icons:['assets/symbioMate.svg'],official:false},symbioBomb:{id:'symbioBomb',en:'SymbioBomb',zh:'共生炸弹',effect:'一次性共生战术装备。',icons:['assets/symbioBomb.svg'],official:false},powerUp1:{id:'powerUp1',en:'Power-Up 1',zh:'吸取强化 +1',effect:'Protheion：VITA比初始增加1。',icons:['assets/vendor/wiki/power-up0.jpg'],official:true},powerUp2:{id:'powerUp2',en:'Power-Up 2',zh:'吸取强化 +2',effect:'Protheion：VITA比初始增加2（上限）。',icons:['assets/vendor/wiki/power-up20.jpg'],official:true},nwi:{id:'nwi',en:'No Wound Incapacitation',zh:'无伤失能 NWI',effect:'忽略昏迷效果；再次受伤移除，可接受救治。',icons:['assets/vendor/wiki/nwi0.jpg'],official:true},dogged:{id:'dogged',en:'Dogged',zh:'顽强 Dogged',effect:'本玩家回合继续行动；不能救治，状态阶段移除。',icons:['assets/vendor/wiki/dogged0.jpg'],official:true}};
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function actualKeys(u,units=[]){if(!S.present(u))return ['dead'];const keys=[...(u.states||[])];if(u.proxyActive)keys.push('proxyActive');if(u.transmuted)keys.push('transmuted');if(u.symbioMate)keys.push('symbioMate');if(u.symbioBomb)keys.push('symbioBomb');if(u.powerUp)keys.push('powerUp'+Math.min(2,u.powerUp));if(S.isProne(u))keys.push('prone');if(!u.isDeployable&&S.active(u)&&units.some(v=>!v.isDeployable&&v.id!==u.id&&v.team!==u.team&&S.active(v)&&E.edgeDistance(u,v)<.025))keys.push('engaged');return [...new Set(keys)].filter(k=>BY_ID[k]||SURVIVAL[k]||k==='unconscious2');}
export function tokens(u,units=[]){const actual=actualKeys(u,units),keys=[...new Set([...actual,...(u.displayStates||[]).filter(k=>k!=='dead')])];const visible=keys.filter(k=>!(k==='prone'&&S.unconscious(u)));return (visible.length?visible:['normal']).map(key=>{const data=SURVIVAL[key]||BY_ID[key==='unconscious2'?'unconscious':key];if(!data)return null;const variant=Math.min(data.icons.length-1,Math.max(0,u.tokenVariants?.[data.id]||0));return {...data,key,posture:S.unconscious(u)&&['unconscious','unconscious2'].includes(key)&&S.isProne(u)?'已俯卧':'',zh:key==='unconscious2'?'昏迷 II':data.zh,icon:data.icons[variant],copies:key==='unconscious2'?2:1,manual:!actual.includes(key)&&key!=='normal',variant};}).filter(Boolean);}
export function badges(u,units=[],compact=false){return tokens(u,units).map(t=>`<span class="tokenBadge ${t.manual?'illustrative':''}" title="${esc(t.en+'：'+t.effect+(t.manual?'（教学标注，未应用规则效果）':'')+(t.official?'':'（辅助 UI 图标）'))}"><img src="${t.icon}" alt="${esc(t.zh)}${t.official?'官方标记':'界面图标'}">${t.copies===2?`<img src="${t.icon}" alt="第二枚昏迷标记">`:''}${compact?'':`<span>${esc(t.zh)}${t.posture?'<small>'+t.posture+'</small>':''}${t.manual?'<small>教学标注</small>':''}${!t.official?'<small>界面图标</small>':''}</span>`}</span>`).join('');}
export function mapTokens(u,units){
 if(!S.onTable(u))return '';const visibility=HO.publicTokens(u,units),list=tokens(u,units).filter(t=>t.key!=='holomask'&&(!visibility.hideHolo||t.key!=='holoecho'));if(visibility.showHolo)list.push({...BY_ID.holoecho,key:'holoecho',icon:BY_ID.holoecho.icons[0],copies:1});if(!list.length)return '';if(list.length===1&&list[0].id==='normal')return '';
 const size=.68,gap=.1,cols=Math.min(4,list.length),rows=Math.ceil(list.length/cols),w=cols*(size+gap)-gap,h=rows*(size+gap)-gap,r=E.radius(u),x=E.clamp(u.x+r+.25,0,48-w),y=E.clamp(u.y-r,0,48-h);
 return `<g class="mapStateTokens" data-bounds="${x},${y},${w},${h}" data-anchor="${u.x},${u.y},${r+.25}">${list.map((t,i)=>{const tx=x+(i%cols)*(size+gap),ty=y+Math.floor(i/cols)*(size+gap);return `<g role="img" aria-label="${esc(t.zh+(t.posture?' · '+t.posture:''))}"><title>${esc(t.zh+'：'+t.effect)}</title><rect x="${tx}" y="${ty}" width="${size}" height="${size}" rx=".12" fill="#102128" stroke="#718e94" stroke-width=".035"/><image href="${t.icon}" x="${tx+.03}" y="${ty+.03}" width="${size-.06}" height="${size-.06}"/>${t.copies===2?`<text x="${tx+size-.03}" y="${ty+size-.02}" text-anchor="end" font-size=".3" fill="white" stroke="#102128" stroke-width=".1" paint-order="stroke">II</text>`:''}</g>`;}).join('')}</g>`;
}
// The invisible marker never captures clicks. A stable geometric hover region
// avoids opacity toggling back and forth when a marker disappears.
export function updateMapTokenHover(svg,p){for(const g of svg.querySelectorAll('.mapStateTokens')){const [x,y,w,h]=g.dataset.bounds.split(',').map(Number),[ux,uy,r]=g.dataset.anchor.split(',').map(Number);const hide=p&&((p.x>=x-.15&&p.x<=x+w+.15&&p.y>=y-.15&&p.y<=y+h+.15)||Math.hypot(p.x-ux,p.y-uy)<=r);g.style.opacity=hide?'0':'1';}}
export function atlasHTML(u,units=[],busy=false){const actual=actualKeys(u,units);return `<header class="stateAtlasHead"><small>N5.3 · FAQ V0.1 · 核对 2026-10-19</small><h2>23 种状态 · 官方标记图鉴</h2><p>含 Normal（正常），其余 22 项；等级、编号和颜色变体不另计数。Normal 可以与非 Null 状态并存，地图默认省略。</p><p>18 项状态有官方标记图；5 项无独立 token，使用虚线边框的辅助界面图标。隐藏信息仅在本单机教学视角明示。</p><a href="https://infinitythewiki.com/States" target="_blank" rel="noreferrer">官方完整状态目录 ↗</a><label class="field">搜索状态<input id="stateSearch" type="search" placeholder="中文、英文或 IMM / CAMO / IMP…"></label><p>当前单位：<b>${esc(u.name)}</b>。下方“教学标注”只用于展示，不会自动实现尚未支持的状态规则。</p></header><div class="stateCatalog">${CATALOG.map(t=>{const on=(u.displayStates||[]).includes(t.id),isActual=actual.includes(t.id)||(t.id==='unconscious'&&actual.includes('unconscious2'));return `<article class="stateCard" data-state-search="${esc((t.zh+' '+t.en+' '+(t.alias||'')+' '+t.id+' '+t.icons.join(' ')).toLowerCase())}"><div class="stateIcons">${t.icons.map((icon,i)=>`<img src="${icon}" alt="${esc(t.zh)}${t.icons.length>1?' 标记 '+(i+1):''}" loading="lazy">`).join('')}</div><h3>${esc(t.zh)} <small>${esc(t.en)}</small></h3><span class="sourceTag">${t.official?'官方 Wiki 原图':'辅助 UI 图标 · 非官方 token'}</span><p>${esc(t.effect)}</p><div class="cardFoot"><a href="${t.source}" target="_blank" rel="noreferrer">规则原文 ↗</a><button data-annotate="${t.id}" ${busy||isActual||['normal','dead'].includes(t.id)?'disabled':''}>${isActual?'当前已生效':t.id==='normal'?'默认省略':t.id==='dead'?'移除桌面，无地图标记':on?'移除教学标注':'标注到单位旁'}</button></div>${t.icons.length>1?`<label class="field">图标变体<select data-token-variant="${t.id}" ${busy?'disabled':''}>${t.icons.map((_,i)=>`<option value="${i}" ${(u.tokenVariants?.[t.id]||0)===i?'selected':''}>${t.id==='impersonation'?'IMP-'+(i+1):t.id==='camouflaged'?['黄色 / 无拟态','绿色 / −3','蓝色 / −6'][i]:'副本 '+(i+1)}</option>`).join('')}</select></label>`:''}</article>`;}).join('')}</div>`;}
